mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("values=[7,13,11] random=[null,0,1]","7:null,13:0,11:1"),
        ("values=[1] random=[null]","1:null"),
        ("values=[1,2] random=[1,0]","1:1,2:0"),
        ("values=[9] random=[0]","9:0"),
        ("values=[3,4,5] random=[2,null,0]","3:2,4:null,5:0"),
        ("  \nvalues=[7,13,11] random=[null,0,1]\n  ","7:null,13:0,11:1"),
        ("\nvalues=[3,4,5] random=[2,null,0]\n","3:2,4:null,5:0")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS copy-random-list");
}
